//! UI fixture that should *not* trigger the bumpy road lint.
//!
//! Branching here is generated by macros or confined to one small macro
//! argument, so no separated clusters form.

fn report(value: Option<i32>, a: bool, b: bool, c: bool) {
    assert!(a && b && c);
    let present = matches!(value, Some(_));
    println!("{}", if present { 1 } else { 0 });
}

fn main() {
    report(Some(1), true, true, true);
}